package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"

	wm "ryoku-wm"
)

func umbrielConfigDir() string {
	if base := os.Getenv("XDG_CONFIG_HOME"); base != "" {
		return filepath.Join(base, "umbriel")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".config", "umbriel")
}

// apply writes both generated files even when empty: config.toml includes them
// by name and Umbriel has no optional-include escape hatch.
func writeGenerated(input, binds string) error {
	dir := umbrielConfigDir()
	if dir == "" {
		return fmt.Errorf("apply: no Umbriel config dir")
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	files := map[string]string{
		"settings.toml": "# Generated by ryoku-wm-umbriel apply; do not edit.\n# Put durable overrides in user.toml.\n" + input,
		"rebinds.toml":  "# Generated by ryoku-wm-umbriel apply; do not edit.\n# Change chords in Settings; hand overrides belong in user.toml.\n" + binds,
	}
	for name, body := range files {
		if err := atomicWrite(filepath.Join(dir, name), []byte(body), 0o644); err != nil {
			return err
		}
	}
	return nil
}

func runApply(args []string) error {
	preview := false
	path := ""
	for _, a := range args {
		if a == "--preview" {
			preview = true
			continue
		}
		if path == "" {
			path = a
		}
	}
	if path == "" {
		return fmt.Errorf("apply: missing store path")
	}
	store, err := readStore(path)
	if err != nil {
		return err
	}
	inputSections, inputUnhonored, inputMapped := inputSettings(store)
	wmSections, wmUnhonored, wmMapped := wmSettings(store)
	sections := map[string]map[string]string{}
	for _, part := range []map[string]map[string]string{inputSections, wmSections} {
		for table, values := range part {
			if sections[table] == nil {
				sections[table] = map[string]string{}
			}
			for key, value := range values {
				sections[table][key] = value
			}
		}
	}
	rebinds, disabled := storeBinds(store)
	bindsTable, bindUnhonored := renderBinds(rebinds, disabled)
	if !preview {
		if err := writeGenerated(renderInputToml(sections), bindsTable); err != nil {
			return err
		}
	}
	allMapped := map[string]bool{}
	for k := range inputMapped {
		allMapped[k] = true
	}
	for k := range wmMapped {
		allMapped[k] = true
	}
	unhonored := append(append(inputUnhonored, wmUnhonored...), bindUnhonored...)
	unhonored = append(unhonored, unconsumedLeaves(store, allMapped)...)
	report := wm.ApplyReport{
		Provider:  "umbriel",
		Unhonored: unhonored,
	}
	if !preview {
		report.Written = []string{"umbriel/settings.toml", "umbriel/rebinds.toml"}
	}
	return json.NewEncoder(stdout).Encode(report)
}

// unconsumedLeaves reports stored settings no writer consumed. Without this a
// stored appearance or window-rule section would be silently dropped in a
// switch preview and the Hub could not tell the user what would not apply.
func unconsumedLeaves(store map[string]any, mapped map[string]bool) []wm.Unhonored {
	var out []wm.Unhonored
	for _, group := range []string{"desktop", "wm"} {
		obj, ok := store[group].(map[string]any)
		if !ok {
			continue
		}
		sections := make([]string, 0, len(obj))
		for section := range obj {
			sections = append(sections, section)
		}
		sort.Strings(sections)
		for _, section := range sections {
			// Rebinds are consumed by storeBinds and reported through the
			// keybind resolver; other desktop maps are leaf settings.
			if group == "desktop" && (section == "keybindRebinds" || section == "keybindDisabled") {
				continue
			}
			leaves, ok := obj[section].(map[string]any)
			if !ok {
				continue
			}
			keys := make([]string, 0, len(leaves))
			for k := range leaves {
				full := group + "." + section + "." + k
				if !mapped[full] {
					keys = append(keys, k)
				}
			}
			sort.Strings(keys)
			for _, k := range keys {
				reason := "Umbriel has no matching setting for this option."
				if group == "desktop" && section == "input" {
					switch k {
					case "workspaceSwipe", "swipeFingers", "swipeInvert", "swipeCreateNew", "swipeDistance":
						reason = "Umbriel's touchpad workspace swipe is built in, with no setting for fingers, distance, direction or new workspaces."
					}
				}
				out = append(out, wm.Unhonored{Key: group + "." + section + "." + k, Reason: reason})
			}
		}
	}
	return out
}

// storeBinds reads the neutral desktop keys the Hub's Shortcuts page writes.
// Both are optional: a store with no rebind section still renders the shipped
// table unchanged.
func storeBinds(store map[string]any) (map[string]string, []string) {
	rebinds := map[string]string{}
	var disabled []string
	desktop, ok := store["desktop"].(map[string]any)
	if !ok {
		return rebinds, disabled
	}
	for key, value := range desktop {
		switch key {
		case "keybindRebinds":
			if m, ok := value.(map[string]any); ok {
				for from, to := range m {
					if s, ok := to.(string); ok {
						rebinds[from] = s
					}
				}
			}
		case "keybindDisabled":
			if list, ok := value.([]any); ok {
				for _, item := range list {
					if s, ok := item.(string); ok {
						disabled = append(disabled, s)
					}
				}
			}
		}
	}
	return rebinds, disabled
}

func readStore(path string) (map[string]any, error) {
	body, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var store map[string]any
	if err := json.Unmarshal(body, &store); err != nil {
		return nil, err
	}
	return store, nil
}
